// ID generation is the only non-deterministic helper of the domain layer.
// Reducers never call it: IDs are generated by action creators and passed in payloads.

function randomHex(bytes: number): string {
	const buf = new Uint8Array(bytes);
	crypto.getRandomValues(buf);
	let out = '';
	for (const b of buf) out += b.toString(16).padStart(2, '0');
	return out;
}

/** Time-ordered unique id (ULID-like: 12 hex chars of ms time + 10 random hex). */
export function newId(prefix: string): string {
	const time = Date.now().toString(16).padStart(12, '0');
	return `${prefix}-${time}${randomHex(5)}`;
}

export function newActionId(): string {
	return newId('act');
}
